CREATE OR REPLACE FUNCTION award_badge(p_user_id INT, p_badge_name TEXT)
RETURNS TEXT AS $$
DECLARE
  v_count INT;
BEGIN
  -- Check if already earned
  SELECT COUNT(*) INTO v_count
  FROM   user_badges
  WHERE  user_id = p_user_id AND badge_name = p_badge_name;

  IF v_count > 0 THEN
    RETURN 'already_earned';
  END IF;

  -- Award the badge
  INSERT INTO user_badges (user_id, badge_name, earned_at)
  VALUES (p_user_id, p_badge_name, NOW());

  RETURN 'awarded';
END;
$$ LANGUAGE plpgsql;
